       "path": "labs/mod-2-4/requirements.txt",
       "name": "requirements.txt",
       "kind": "config",
       "label": {
        "id": "Konfigurasi dependensi dagster dan pytest",
        "en": "dagster and pytest"
       },
       "code": "dagster>=1.8\npytest>=8"
